	["search recipes"] = "chercher des recettes",
	["%s opened, and listed nothing"] = "%s ouvert, et rien listé",
	["A profession that makes things and lists nothing is usually another addon filtering or replacing that window - open it again with those switched off."] = "Un métier qui fabrique des choses et n'en liste aucune, c'est presque toujours un autre addon qui filtre ou remplace cette fenêtre - rouvrez-la une fois ceux-ci désactivés.",
	["%s never opened"] = "%s jamais ouverts",
	["|cffffd700Sort by|r"] = "|cffffd700Trier par|r",
